<?php
if ( php_sapi_name() !== 'cli' ) { exit; } // solo terminal, nunca via web
/**
 * HOMVUK Portal - SafeCard (hvkp-safecard)
 *
 * Mejora las instrucciones de acceso al condominio en el Check-in del portal:
 *  1. Sube las imagenes de la App SafeCard (pantallas + logo) a uploads/portal.
 *  2. Reemplaza los pasos "Ingreso al Condominio" y "Consejos para Entrar y
 *     Salir" por un unico paso ilustrado, en los 3 idiomas y ambas unidades:
 *     - Peatonal: App OBLIGATORIA para entrar Y salir (QR del torniquete).
 *     - Vehicular: App (boton verde) o patente registrada (barrera automatica).
 *
 * Solo toca la base de datos y archivos de imagen (nada de PHP persistente).
 *
 * Uso:  php hvkp-safecard.php            (instalar)
 *       php hvkp-safecard.php restore    (revertir)
 */

$HVKA_IMG_B64  = '';
$HVKA_IMG_MD5  = 'f35b071740f5f200a4a80e9ebec995e7';
$HVKA_LOGO_B64 = '';
$HVKA_LOGO_MD5 = '1a95b046efac4041c2ba8b8a7f987db7';
$HVKA_BLOCKS   = array(
    'es'   => '',
    'en'   => '',
    'ptbr' => '',
);

/**
 * Reemplaza los bloques <h4> que hablan de SafeCard por un unico bloque nuevo.
 * Devuelve array( html_nuevo|null, motivo ).
 */
function hvka_sc_replace( $html, $nuevo ) {
    if ( ! is_string( $html ) || '' === trim( $html ) ) {
        return array( null, 'contenido-vacio' );
    }
    if ( false !== strpos( $html, 'safecard-app.jpg' ) ) {
        return array( null, 'ya-instalado' );
    }
    $partes = preg_split( '/(?=<h4>)/i', $html );
    $salida = '';
    $puesto = false;
    $reemplazados = 0;
    foreach ( $partes as $parte ) {
        if ( '' === trim( $parte ) ) {
            continue;
        }
        $es_h4 = ( 0 === stripos( ltrim( $parte ), '<h4>' ) );
        if ( $es_h4 && preg_match( '/safecard/i', $parte ) ) {
            $reemplazados++;
            if ( ! $puesto ) {
                $salida .= $nuevo;
                $puesto  = true;
            }
            continue;
        }
        $salida .= $parte;
    }
    if ( ! $puesto ) {
        return array( null, 'no-se-encontraron-pasos-safecard' );
    }
    if ( substr_count( strtolower( $salida ), '<h4>' ) < 1 ) {
        return array( null, 'resultado-sin-pasos' );
    }
    return array( $salida, 'ok:' . $reemplazados );
}

// ---- Pruebas locales (sin WordPress): HVKASC_TEST=1 php hvkp-safecard.php ----
if ( getenv( 'HVKASC_TEST' ) ) {
    $fail = 0;
    $chk  = function ( $l, $c ) use ( &$fail ) {
        echo ( $c ? "[OK]    " : "[ERROR] " ) . $l . "\n";
        if ( ! $c ) { $fail++; }
    };
    $nuevo = base64_decode( $GLOBALS['HVKA_BLOCKS']['es'] );
    $orig  = '<h3>Check-in</h3><p>intro</p>'
        . '<h4>Paso 1: Check-in en Conserjeria</h4><p>conserje</p>'
        . '<h4>Ingreso al Condominio</h4><ol><li>Descarga la App de <strong>SafeCard</strong>.</li></ol>'
        . '<h4>Consejos para Entrar y Salir del Condominio</h4><ul><li>App de SafeCard</li></ul>'
        . '<h4>Ingreso al Edificio y Estacionamientos</h4><p>control remoto N&deg; 19</p>'
        . '<h4>Ingreso al Departamento</h4><p>codigo 1960</p>';
    list( $out, $why ) = hvka_sc_replace( $orig, $nuevo );
    $chk( 'reemplaza los 2 pasos SafeCard por 1', 'ok:2' === $why );
    $chk( 'quedan 4 pasos (conserjeria + nuevo + edificio + departamento)', 4 === substr_count( strtolower( $out ), '<h4>' ) );
    $chk( 'conserva conserjeria, estacionamiento y departamento', strpos( $out, 'Conserjeria' ) !== false && strpos( $out, 'N&deg; 19' ) !== false && strpos( $out, '1960' ) !== false );
    $chk( 'conserva el intro', strpos( $out, '<p>intro</p>' ) !== false );
    $chk( 'incluye imagen de la app y logo', strpos( $out, 'safecard-app.jpg' ) !== false && strpos( $out, 'safecard-logo.png' ) !== false );
    $chk( 'menciona peatonal obligatorio entrar y salir', stripos( $out, 'entrar Y para salir' ) !== false );
    $chk( 'menciona patente y barrera automatica', stripos( $out, 'patente' ) !== false && stripos( $out, 'abre sola' ) !== false );
    $chk( 'orden: nuevo paso va donde estaba el primero', strpos( $out, 'Acceso al Condominio' ) < strpos( $out, 'Ingreso al Edificio' ) );
    list( $out2, $why2 ) = hvka_sc_replace( $out, $nuevo );
    $chk( 'idempotente', null === $out2 && 'ya-instalado' === $why2 );
    list( $out3, $why3 ) = hvka_sc_replace( '<h4>Otro paso</h4><p>sin menciones de la app</p>', $nuevo );
    $chk( 'sin pasos SafeCard: no toca nada', null === $out3 );
    list( $out4, $why4 ) = hvka_sc_replace( '', $nuevo );
    $chk( 'contenido vacio: rechazado', null === $out4 );
    foreach ( array( 'es', 'en', 'ptbr' ) as $l ) {
        $b = base64_decode( $GLOBALS['HVKA_BLOCKS'][ $l ] );
        $chk( "bloque $l valido", 0 === stripos( $b, '<h4>' ) && strpos( $b, 'safecard-app.jpg' ) !== false );
    }
    $chk( 'imagen md5', md5( base64_decode( $GLOBALS['HVKA_IMG_B64'] ) ) === $GLOBALS['HVKA_IMG_MD5'] );
    $chk( 'logo md5', md5( base64_decode( $GLOBALS['HVKA_LOGO_B64'] ) ) === $GLOBALS['HVKA_LOGO_MD5'] );
    echo $fail ? "FALLARON $fail pruebas\n" : "TODAS LAS PRUEBAS PASARON\n";
    exit( $fail ? 1 : 0 );
}

// ---- Ejecucion real ----
require __DIR__ . '/wp-load.php';
global $wpdb;

$mode  = isset( $argv[1] ) ? $argv[1] : 'install';
$ok    = array();
$warn  = array();
$tabla = $wpdb->prefix . 'portal_units';

if ( 'restore' === $mode ) {
    $b = get_option( 'hvkp_safecard_backup' );
    if ( ! is_array( $b ) || empty( $b ) ) {
        echo "[AVISO] No hay respaldo; nada que restaurar.\n";
        exit( 0 );
    }
    foreach ( $b as $fila ) {
        $wpdb->update( $tabla, array( $fila['campo'] => $fila['valor'] ), array( 'id' => (int) $fila['id'] ) );
    }
    echo "[OK]    Contenido de check-in restaurado (" . count( $b ) . " campos)\n";
    exit( 0 );
}

// 1) Imagenes a uploads/portal (archivos no-PHP, sobreviven al antivirus)
$updir = wp_upload_dir();
$dir   = trailingslashit( $updir['basedir'] ) . 'portal';
if ( ! is_dir( $dir ) ) {
    wp_mkdir_p( $dir );
}
$imgs = array(
    'safecard-app.jpg'  => array( $HVKA_IMG_B64, $HVKA_IMG_MD5 ),
    'safecard-logo.png' => array( $HVKA_LOGO_B64, $HVKA_LOGO_MD5 ),
);
foreach ( $imgs as $nombre => $par ) {
    $bin = base64_decode( $par[0] );
    if ( md5( $bin ) !== $par[1] ) {
        echo "[ERROR] La imagen $nombre no paso la verificacion md5. Nada fue modificado.\n";
        exit( 1 );
    }
    file_put_contents( $dir . '/' . $nombre, $bin );
    if ( md5_file( $dir . '/' . $nombre ) === $par[1] ) {
        $ok[] = "Imagen instalada: uploads/portal/$nombre";
    } else {
        echo "[ERROR] No se pudo escribir $nombre.\n";
        exit( 1 );
    }
}

// 2) Contenido de check-in en los 3 idiomas y todas las unidades
$unidades = $wpdb->get_results( "SELECT id, slug, name FROM $tabla WHERE active = 1" );
if ( ! $unidades ) {
    echo "[ERROR] No se encontraron unidades activas.\n";
    exit( 1 );
}
$backup = array();
foreach ( $unidades as $u ) {
    foreach ( $HVKA_BLOCKS as $lang => $b64 ) {
        $campo = 'checkin_' . $lang;
        $actual = $wpdb->get_var( $wpdb->prepare( "SELECT `$campo` FROM $tabla WHERE id = %d", $u->id ) );
        list( $nuevo, $motivo ) = hvka_sc_replace( (string) $actual, base64_decode( $b64 ) );
        if ( 'ya-instalado' === $motivo ) {
            $ok[] = "$u->name [$lang]: ya estaba actualizado";
            continue;
        }
        if ( null === $nuevo ) {
            $warn[] = "$u->name [$lang]: sin cambios ($motivo)";
            continue;
        }
        $backup[] = array( 'id' => (int) $u->id, 'campo' => $campo, 'valor' => (string) $actual );
        $wpdb->update( $tabla, array( $campo => $nuevo ), array( 'id' => (int) $u->id ) );
        $ok[] = "$u->name [$lang]: acceso SafeCard ilustrado instalado ($motivo)";
    }
}
if ( $backup ) {
    update_option( 'hvkp_safecard_backup', $backup, false );
}

// 3) Purga de caches
if ( function_exists( 'wp_cache_flush' ) ) { wp_cache_flush(); }
do_action( 'litespeed_purge_all' );
if ( function_exists( 'rocket_clean_domain' ) ) { rocket_clean_domain(); }
if ( function_exists( 'w3tc_flush_all' ) ) { w3tc_flush_all(); }
$ok[] = 'Caches purgadas';

// 4) Verificacion: imagenes accesibles publicamente
foreach ( array_keys( $imgs ) as $nombre ) {
    $url  = trailingslashit( $updir['baseurl'] ) . 'portal/' . $nombre;
    $resp = wp_remote_head( $url, array( 'timeout' => 20, 'sslverify' => false ) );
    $code = is_wp_error( $resp ) ? 0 : (int) wp_remote_retrieve_response_code( $resp );
    if ( 200 === $code ) {
        $ok[] = "Verificado: $nombre accesible ($url)";
    } else {
        $warn[] = "No se pudo verificar $nombre (HTTP $code)";
    }
}

echo "== HOMVUK Portal - Acceso SafeCard ilustrado ==\n";
foreach ( $ok as $m )   { echo "[OK]    $m\n"; }
foreach ( $warn as $m ) { echo "[AVISO] $m\n"; }
echo "Listo. Este instalador puede borrarse: rm -f hvkp-safecard.php\n";
echo "Para revertir: php hvkp-safecard.php restore\n";
